\sheettitle{Fiche 6}{Indices statistiques -- CORRIGÉ DÉTAILLÉ}{Badr ABOUFARASSE, PhD. -- Année universitaire 2026--2027}

\solution{Corrigé -- Exercice 1}
\[
I_{2024/2023}=\frac{92}{80}100=\boxed{115}.
\]
\[
I_{2025/2024}=\frac{101,2}{92}100=\boxed{110}.
\]
\[
I_{2025/2023}=\frac{101,2}{80}100=\boxed{126,5}.
\]
Circularité :
\[
\frac{I_{2024/2023}\times I_{2025/2024}}{100}=\frac{115\times110}{100}=126,5=I_{2025/2023}.
\]
Réversibilité :
\[
I_{2023/2025}=\frac{80}{101,2}100=79,0514,
\]
\[
I_{2025/2023}\times I_{2023/2025}=126,5\times79,0514\approx10000.
\]
Un indice $>100$ indique une hausse par rapport à la période de référence ; un indice $<100$ indique une baisse.

\solution{Corrigé -- Exercice 2}
Tableau des produits :
\begin{center}\small
\begin{tabular}{crrrr}
\toprule
Produit&$p_0q_0$&$p_0q_1$&$p_1q_0$&$p_1q_1$\\\midrule
A&1060&1325&1240&1550\\
B&1148&1394&1456&1768\\
C&2625&2850&2870&3116\\
D&750&825&1140&1254\\\midrule
Total&5583&6394&6706&7688\\\bottomrule
\end{tabular}
\end{center}

Indices de prix :
\[
L^p=\frac{\sum p_1q_0}{\sum p_0q_0}100=\frac{6706}{5583}100=\boxed{120,11},
\]
\[
P^p=\frac{\sum p_1q_1}{\sum p_0q_1}100=\frac{7688}{6394}100=\boxed{120,24}.
\]
Indices de quantité :
\[
L^q=\frac{\sum p_0q_1}{\sum p_0q_0}100=\frac{6394}{5583}100=\boxed{114,53},
\]
\[
P^q=\frac{\sum p_1q_1}{\sum p_1q_0}100=\frac{7688}{6706}100=\boxed{114,64}.
\]
Fisher :
\[
F^p=\sqrt{120,11\times120,24}=\boxed{120,18},
\]
\[
F^q=\sqrt{114,53\times114,64}=\boxed{114,58}.
\]
Indice de valeur :
\[
I_v=\frac{7688}{5583}100=\boxed{137,70}.
\]
Interprétation : entre 2005 et 2011, le niveau des prix augmente d'environ $20,18\%$ selon Fisher, les quantités d'environ $14,58\%$, et la valeur totale d'environ $37,70\%$.

\solution{Corrigé -- Exercice 3}
\[
\sum p_0q_0=100(14)+60(10)+160(4)=2640,
\]
\[
\sum p_1q_0=150(14)+50(10)+140(4)=3160,
\]
\[
\sum p_0q_1=100(10)+60(12)+160(5)=2520,
\]
\[
\sum p_1q_1=150(10)+50(12)+140(5)=2800.
\]
Alors
\[
L^p=\frac{3160}{2640}100=119,70,\qquad P^p=\frac{2800}{2520}100=111,11,
\]
\[
F^p=\sqrt{119,70\times111,11}=\boxed{115,33\ \text{environ}}.
\]

\end{document}

